import type { Activity } from '../types';

/** Активності за віковими вікнами. Одна картка = гра + пояснення саме для неї. */
export const activities: Activity[] = [
  { id: 'a001', from: 0, to: 6, minutes: 5, title: 'Обличчям до обличчя', text: 'Тримайте малюка на відстані витягнутої долоні від свого обличчя та просто дивіться одне на одного. Повільно висуньте язик, зачекайте, повторіть.', why: 'У цьому віці він чітко бачить приблизно на 25 см — саме ваше обличчя. Повторення простого руху запускає перші дзеркальні реакції.' },
  { id: 'a002', from: 0, to: 6, minutes: 5, title: 'Шкіра до шкіри', text: 'Роздягніть малюка до підгузка, покладіть собі на груди й накрийте пледом. Нічого не робіть — просто дихайте разом.', why: 'Контакт шкіра до шкіри допомагає диханню й температурі налаштуватися на ваші. Для нервової системи це зрозумілий сигнал «я в безпеці».' },
  { id: 'a003', from: 0, to: 6, minutes: 3, title: 'Один голос', text: 'Розкажіть уголос, що робите: «зараз змінимо підгузок, потім підійдемо до вікна». Говоріть рівним тихим голосом.', why: 'Він упізнає ваш голос від народження — чув його ще до появи на світ. Знайомий звук знижує напруження швидше за заколисування.' },
  { id: 'a004', from: 0, to: 6, minutes: 4, title: 'Чорне й біле', text: 'Покажіть аркуш із великим чорно-білим візерунком, потримайте збоку й повільно ведіть до центру.', why: 'Кольори малюк поки розрізняє нечітко, зате добре бачить високий контраст. Стеження за повільним рухом тренує м’язи очей.' },
  { id: 'a005', from: 0, to: 6, minutes: 5, title: 'Животик уперше', text: 'Покладіть малюка животиком на свої груди, обличчям до себе. Почніть з однієї хвилини кілька разів на день.', why: 'У цьому положенні він вчиться підіймати голову — це основа для перевороту й опори на руки.' },
  { id: 'a006', from: 7, to: 12, minutes: 6, title: 'Розмова з паузами', text: 'Малюк каже «ааа» — ви відповідаєте й замовкаєте. Зробіть паузу, дайте йому додати свій звук.', why: 'Так народжується черга в розмові: спершу один, потім інший. Пауза важливіша за самі слова.' },
  { id: 'a007', from: 7, to: 12, minutes: 5, title: 'Брязкальце збоку', text: 'Подзвоніть брязкальцем праворуч, дочекайтеся, поки він поверне голову, потім зробіть те саме ліворуч.', why: 'Він вчиться пов’язувати звук із місцем. Поворот до джерела — перший крок до пошуку очима того, що він чує.' },
  { id: 'a008', from: 7, to: 12, minutes: 5, title: 'Велосипед', text: 'Лежачи на спині, м’яко згинайте й розгинайте ніжки по черзі, промовляючи ритмічне «раз-два».', why: 'Ритмічний рух допомагає відчути межі власного тіла — саме так мозок вибудовує його карту.' },
  { id: 'a009', from: 7, to: 12, minutes: 4, title: 'Усмішка у відповідь', text: 'Спіймайте його погляд і усміхніться. Дочекайтеся усмішки у відповідь — та усміхніться знову.', why: 'Усмішка у відповідь з’являється близько шести тижнів. Кожен такий обмін зміцнює зв’язок між вами сильніше за будь-яку іграшку.' },
  { id: 'a010', from: 7, to: 12, minutes: 6, title: 'Прогулянка кімнатою', text: 'Носіть малюка на руках і показуйте предмети, називаючи їх: «це вікно», «це лампа». Затримуйтеся біля кожного.', why: 'Він почав розрізняти краї та візерунки. Предмети, названі вголос, згодом стануть першими впізнаними словами.' },
  { id: 'a011', from: 13, to: 18, minutes: 10, title: 'Тканини на дотик', text: 'Дайте по черзі торкнутися трьох різних тканин — махрового рушника, шовку, в’язаного шарфа. Називайте вголос, чого він торкається.', why: 'Долоні зараз чутливіші, ніж будь-коли потім. Різна фактура дає мозку матеріал для порівняння — так виникає поняття «різне».' },
  { id: 'a012', from: 13, to: 18, minutes: 8, title: 'Дотягнутися', text: 'Підвісьте іграшку так, щоб малюк ледве діставав. Не підносьте ближче — нехай тягнеться сам.', why: 'Рука й око щойно навчилися працювати разом. Кожна спроба дістати — тренування цього зв’язку.' },
  { id: 'a013', from: 13, to: 18, minutes: 6, title: 'Шурхотливий папір', text: 'Дайте пом’яти аркуш пергаменту або шурхотливу пелюшку. Увесь час будьте поруч.', why: 'Малюк відкриває причину й наслідок: я стиснув — воно зашурхотіло. Це перший експеримент у його житті.' },
  { id: 'a014', from: 13, to: 18, minutes: 5, title: 'Дзеркало', text: 'Підійдіть до дзеркала й потримайте малюка перед ним. Помахайте рукою його відображенню.', why: 'Себе у відображенні він поки не впізнає, але обличчя — найцікавіший об’єкт у світі, а рухоме обличчя й поготів.' },
  { id: 'a015', from: 13, to: 18, minutes: 7, title: 'Опора на руки', text: 'Покладіть малюка на животик і розташуйте перед ним іграшку трохи вище рівня очей, щоб він підвівся подивитися.', why: 'Піднімаючись, він зміцнює спину й шию — те, на чому згодом триматиметься сидіння.' },
  { id: 'a016', from: 19, to: 26, minutes: 8, title: 'Ку-ку', text: 'Закрийте обличчя долонями й відкрийте: «ку-ку!». Повторіть кілька разів, а потім сховайтеся трохи довше.', why: 'Він починає здогадуватися, що сховане не зникло. Гра перевіряє цю здогадку — і щоразу вона підтверджується.' },
  { id: 'a017', from: 19, to: 26, minutes: 10, title: 'Барабан із каструлі', text: 'Переверніть каструлю, дайте дерев’яну ложку. Постукайте самі, а потім дайте спробувати малюкові.', why: 'Він перевіряє: моя дія дає звук завжди чи іноді. Повторюваність результату — основа передбачуваного світу.' },
  { id: 'a018', from: 19, to: 26, minutes: 6, title: 'Дай-візьми', text: 'Простягніть іграшку, дочекайтеся, поки візьме, попросіть повернути її з відкритою долонею. Не забирайте силоміць.', why: 'Обмін предметами — перший діалог без слів: моя черга, твоя черга.' },
  { id: 'a019', from: 19, to: 26, minutes: 7, title: 'Сидимо й дістаємо', text: 'Посадіть малюка з опорою з подушок і розкладіть навколо кілька предметів на відстані руки.', why: 'Сидячи, руки вперше вільні. Дотягнутися й не завалитися — робота над рівновагою.' },
  { id: 'a020', from: 19, to: 26, minutes: 5, title: 'Ім’я з усіх боків', text: 'Покличте малюка на ім’я з різних кутків кімнати й зачекайте, поки він знайде вас очима.', why: 'Власне ім’я він виокремлює з потоку мовлення раніше за інші слова — це точка опори у звуковому хаосі.' },
  { id: 'a021', from: 27, to: 36, minutes: 10, title: 'Коробка зі скарбами', text: 'Складіть у коробку 5–6 безпечних побутових речей: дерев’яну ложку, силіконову формочку, м’яку щітку. Дайте розбирати.', why: 'Звичайні речі цікавіші за іграшки: вони мають різну вагу, звук і температуру. Це багатше за будь-який розвивальний центр.' },
  { id: 'a022', from: 27, to: 36, minutes: 8, title: 'Сховати під хустинку', text: 'На очах у малюка накрийте іграшку хустинкою. Запитайте: «де?». Дайте знайти самостійно.', why: 'Знайти сховане — робота пам’яті. Він утримує в голові образ того, чого не бачить.' },
  { id: 'a023', from: 27, to: 36, minutes: 10, title: 'Тунель із подушок', text: 'Збудуйте короткий прохід із подушок і покличте малюка до себе з іншого боку.', why: 'Повзти до мети — це план із кількох кроків. Мозок вчиться утримувати намір довше за одну секунду.' },
  { id: 'a024', from: 27, to: 36, minutes: 6, title: 'Крихти пінцетом', text: 'Насипте на стіл кілька великих м’яких шматочків їжі й дайте збирати пальцями. Будьте поруч.', why: 'Великий і вказівний пальці вчаться працювати в парі. Та сама навичка згодом допоможе тримати ложку й олівець.' },
  { id: 'a025', from: 27, to: 36, minutes: 7, title: 'Відлуння звуків', text: 'Малюк каже «ба-ба» — повторіть точно так само. Потім додайте склад і подивіться, чи повторить він.', why: 'Він чує, що його звук повернувся. Так белькотіння перетворюється на розмову, а потім на слова.' },
  { id: 'a026', from: 37, to: 46, minutes: 10, title: 'Вкласти одне в одне', text: 'Дайте дві-три миски різного розміру. Покажіть, як маленька входить у велику, далі не втручайтеся.', why: 'Він порівнює розміри на практиці. Це перша математика — ще до будь-яких цифр.' },
  { id: 'a027', from: 37, to: 46, minutes: 8, title: 'Показати пальцем', text: 'Покажіть пальцем на предмет і назвіть його. Почекайте, поки малюк простежить за вашою рукою та покаже сам.', why: 'Спільна увага — «дивимося на те саме» — сильніше за будь-який інший передвісник майбутнього словникового запасу.' },
  { id: 'a028', from: 37, to: 46, minutes: 10, title: 'Ходьба вздовж дивана', text: 'Розкладіть уздовж дивана кілька іграшок на відстані кроку одна від одної.', why: 'Переступаючи з опорою, він переносить вагу з ноги на ногу — пряма репетиція перших кроків.' },
  { id: 'a029', from: 37, to: 46, minutes: 6, title: 'Книга з цупкими сторінками', text: 'Посадіть малюка на коліна й відкривайте сторінки. Не читайте текст — називайте те, що бачите, та дайте гортати самому.', why: 'Гортати й бачити, як змінюється картинка, — теж причина й наслідок. Звичка до книги складається саме зараз.' },
  { id: 'a030', from: 37, to: 46, minutes: 7, title: 'Просте прохання', text: 'Попросіть: «дай м’ячик» — і простягніть руку. Порадійте, навіть якщо він дасть щось інше.', why: 'Розуміння слів значно випереджає мовлення. Він виконує прохання, хоча сам майже не говорить.' },
  { id: 'a031', from: 47, to: 60, minutes: 10, title: 'Ложка власноруч', text: 'Дайте малюкові його ложку й густу їжу — йогурт або пюре. Приготуйтеся до безладу й не виправляйте рух руки.', why: 'Йдеться не про їжу, а про самостійність. Кожна вдала ложка — доказ, що він може впоратися сам.' },
  { id: 'a032', from: 47, to: 60, minutes: 8, title: 'Скласти в кошик', text: 'Поставте кошик і покажіть, як кидати в нього м’ячики. Далі малюк упорається сам.', why: 'Відпустити предмет у потрібну мить складніше, ніж схопити: розтискання пальців потребує окремого контролю.' },
  { id: 'a033', from: 47, to: 60, minutes: 10, title: 'Справжні хованки', text: 'Сховайтеся за дверима й покличте. Дайте малюкові вас знайти.', why: 'Він тримає в голові ваш образ, поки вас не видно, — та сама пам’ять, що допомагає пережити розлуку вдень.' },
  { id: 'a034', from: 47, to: 60, minutes: 7, title: 'Ритуал перед сном', text: 'Складіть ланцюжок із трьох кроків: ванна, піжама, казка. Дотримуйтеся одного й того самого порядку.', why: 'Передбачувана послідовність працює краще за вмовляння: він знає, що буде далі, і не опирається.' },
  { id: 'a035', from: 47, to: 60, minutes: 8, title: 'Карлючки', text: 'Великий аркуш і товста воскова крейда. Покажіть одну лінію й віддайте аркуш малюкові.', why: 'Слід на папері — найочевидніший доказ, що його дія змінює світ.' },
  { id: 'a036', from: 0, to: 6, minutes: 4, title: 'Тиха долоня', text: 'Покладіть розкриту долоню йому на спину, поки він лежить поруч із вами. Кілька хвилин не змінюйте тиску й тихо наспівуйте.', why: 'Рівний дотик дає нервовій системі сталий орієнтир. Так відчуття від шкіри поступово поєднуються з вашим голосом.' },
  { id: 'a037', from: 0, to: 6, minutes: 3, title: 'Світло з вікна', text: 'Підійдіть до вікна й дайте малюкові подивитися на світле небо, прикривши від прямого сонця. Повільно поверніться до світла й назад.', why: 'М’яка зміна яскравості допомагає очам помічати контури. Це зовсім інший зоровий досвід, ніж розглядати обличчя зблизька.' },
  { id: 'a038', from: 0, to: 6, minutes: 5, title: 'Пісня на видиху', text: 'Оберіть коротку колискову й заспівайте її дуже спокійно, розтягуючи останні склади. Повторюйте ту саму мелодію.', why: 'Довгі рівні звуки створюють упізнаваний слуховий малюнок. Мозок починає відрізняти повторювану мелодію від звичайного домашнього шуму.' },
  { id: 'a039', from: 0, to: 6, minutes: 4, title: 'Смужки поруч', text: 'Покладіть поряд картку з широкими чорними смугами й дайте подивитися, не рухаючи її. За хвилину змініть бік.', why: 'Нерухомий контраст допомагає затримати погляд на одному об’єкті. Перенесення картки запрошує очі знайти її знову.' },
  { id: 'a040', from: 0, to: 6, minutes: 5, title: 'Ваші пальці', text: 'Піднесіть один палець до його долоні й дайте обхопити. Повільно змініть руку, нічого не витягаючи з кулачка.', why: 'Хапальний рефлекс поєднує дотик у долоні з рухом пальців. Він уперше відчуває, що рука може втримати щось назовні.' },
  { id: 'a041', from: 0, to: 6, minutes: 3, title: 'Шепіт ліворуч', text: 'Сядьте збоку й скажіть кілька лагідних фраз майже пошепки. Потім пересядьте на інший бік і повторіть.', why: 'Той самий голос із двох боків створює об’ємну звукову картину. Так слух отримує перші підказки про напрямок.' },
  { id: 'a042', from: 0, to: 6, minutes: 4, title: 'Ніс до носа', text: 'Візьміть малюка на руки обличчям до себе й на мить торкніться носом його носа. Зробіть паузу та повторіть, якщо він спокійний.', why: 'Короткий передбачуваний жест легше помітити, ніж довгу гру. Повтор допомагає поєднати ваше обличчя, запах і дотик в одну знайому подію.' },
  { id: 'a043', from: 0, to: 6, minutes: 5, title: 'Повільне віяло', text: 'Візьміть аркуш цупкого паперу й плавно водіть ним на відстані від обличчя, створюючи легкий потік повітря. Стежте, щоб аркуш не торкався обличчя.', why: 'Повітря на шкірі додає відчуття руху без перевантаження. Мозок зіставляє його з тим, що бачать очі.' },
  { id: 'a044', from: 0, to: 6, minutes: 4, title: 'Називаємо пальчики', text: 'Під час переодягання по черзі м’яко торкайтеся стопи, коліна, долоні та плеча, називаючи кожне місце. Робіть це повільно.', why: 'Повторювані дотики в різних місцях збирають перші зв’язки на карті тіла. Слова поки не зрозумілі, але їхній ритм уже супроводжує відчуття.' },
  { id: 'a045', from: 0, to: 6, minutes: 5, title: 'Тінь на стіні', text: 'У світлій кімнаті поворушіть рукою так, щоб на стіні з’явилася м’яка тінь. Зупиніться, потім повторіть рух.', why: 'Тінь змінюється синхронно з рукою, і очі помічають простий зв’язок між рухом та картинкою. Контраст тіні зручний для ще незрілого зору.' },
  { id: 'a046', from: 0, to: 6, minutes: 3, title: 'Ранкове вітання', text: 'Коли малюк прокинувся, підійдіть, назвіть його на ім’я й скажіть одну й ту саму коротку фразу. Робіть це без поспіху.', why: 'Повторюваний початок зустрічі стає знайомою звуковою міткою. Такі маленькі сталі речі роблять день зрозумілішим.' },
  { id: 'a047', from: 0, to: 6, minutes: 5, title: 'Щока до щоки', text: 'Сядьте зручно й на хвилину притуліть свою щоку до його щоки. Потім трохи відсуньтеся, подивіться на малюка та поверніться.', why: 'Тепло шкіри й зміна близькості дають багату, але м’яку сенсорну інформацію. Повернення після паузи підтримує відчуття сталості контакту.' },
  { id: 'a048', from: 0, to: 6, minutes: 4, title: 'Кола долонею', text: 'Намалюйте пальцем повільні кола на його животику поверх одягу, промовляючи «коло-коло». Зупиняйтеся між колами.', why: 'Однакова траєкторія створює повторюваний тілесний малюнок. Паузи дають час помітити початок і кінець відчуття.' },
  { id: 'a049', from: 0, to: 6, minutes: 3, title: 'Біле простирадло', text: 'Розстеліть поряд біле простирадло й покладіть на нього яскраву чорну стрічку поза досяжністю. Дайте спокійно роздивлятися.', why: 'Різка межа між світлим і темним легше розрізняється, ніж дрібні деталі. Погляд вчиться виокремлювати один об’єкт із тла.' },
  { id: 'a050', from: 0, to: 6, minutes: 5, title: 'Рахуємо вдихи', text: 'Тримайте малюка на руках і самі повільно рахуйте вголос до п’яти на кожному своєму видиху. Після рахунку зробіть тиху паузу.', why: 'Повторюваний темп мовлення допомагає розрізняти ритм людського голосу. Для нього це ще не лічба, а спокійна звукова форма.' },
  { id: 'a051', from: 0, to: 6, minutes: 4, title: 'Коліна-гойдалки', text: 'Сядьте, покладіть малюка поперек колін із надійною підтримкою й зовсім трохи нахиляйте коліна праворуч і ліворуч. Стежте за його реакцією.', why: 'Невелика зміна положення знайомить із відчуттям рівноваги. Вестибулярна система отримує сигнал без різких рухів.' },
  { id: 'a052', from: 0, to: 6, minutes: 3, title: 'Розповідь про погоду', text: 'Підійдіть до вікна й двома-трьома реченнями розкажіть, що надворі: дощ, вітер чи сонце. Говоріть рівно.', why: 'Різна інтонація та довжина фраз формують слухову палітру мовлення. Водночас зовнішній світ приходить до малюка через ваш знайомий голос.' },
  { id: 'a053', from: 0, to: 6, minutes: 4, title: 'М’який рушник', text: 'Проведіть краєм чистого м’якого рушника по стопі й долоні, а тоді приберіть його. Не лоскочіть і не поспішайте.', why: 'Тканина відрізняється від рук температурою та фактурою. Контраст двох безпечних відчуттів вчить мозок розділяти джерела дотику.' },
  { id: 'a054', from: 0, to: 6, minutes: 5, title: 'Вікно й голос', text: 'Тримайте малюка біля вікна й спершу мовчіть, потім назвіть те, на що дивитеся. Знову помовчіть, щоб лишилося місце для враження.', why: 'Чергування тиші й голосу робить звук помітним на тлі зорової сцени. Так поступово поєднуються різні канали сприйняття.' },
  { id: 'a055', from: 0, to: 6, minutes: 4, title: 'Плече й пісенька', text: 'Покладіть малюка животиком собі на плече, підтримуючи голову, й наспівайте чотири однакові рядки. Після кожного трохи погладьте спину.', why: 'Положення на плечі змінює огляд і відчуття опори. Однаковий мотив пов’язується з цим особливим видом близькості.' },
  { id: 'a056', from: 7, to: 12, minutes: 6, title: 'Стежимо за стрічкою', text: 'Візьміть яскраву стрічку й повільно проведіть нею дугою перед обличчям малюка, не торкаючись. Зупиніться в центрі, аби він устиг роздивитися.', why: 'Плавна дуга запрошує вести погляд не лише прямо. Очі узгоджують рух в обох частинах поля зору.' },
  { id: 'a057', from: 7, to: 12, minutes: 5, title: 'Відповідь голосному', text: 'Почувши протяжний голосний звук, відповідайте іншим голосним такої самої довжини. Перед наступною відповіддю лишайте тишу.', why: 'Малюк чує схожість і відмінність звуків, які видає сам. Такий обмін тренує слуховий зворотний зв’язок.' },
  { id: 'a058', from: 7, to: 12, minutes: 7, title: 'Погладити щічки', text: 'Легко проведіть пальцями від середини щічок до вушок, потім зробіть паузу. Повторіть кілька разів, дивлячись малюкові в обличчя.', why: 'Симетричні дотики допомагають зіставляти лівий і правий бік обличчя. Зоровий контакт додає відчуттям спільного сенсу.' },
  { id: 'a059', from: 7, to: 12, minutes: 5, title: 'Дзвіночок вище', text: 'Подзвенить невеликим дзвіночком трохи вище грудей малюка й дочекайтеся погляду. Повільно опустіть джерело звуку нижче, не нахиляючи його голову.', why: 'Звук у різних точках простору спонукає шукати джерело очима. Слухова підказка поєднується з напрямком угору й униз.' },
  { id: 'a060', from: 7, to: 12, minutes: 6, title: 'Ніжки в шкарпетках', text: 'Одягніть шкарпетки з різними візерунками й на хвилину підніміть ніжки так, щоб малюк їх побачив. Повільно поворушіть стопами.', why: 'Власні ніжки стають цікавим рухомим об’єктом. Малюк помічає, як картинка змінюється разом із його тілом.' },
  { id: 'a061', from: 7, to: 12, minutes: 4, title: 'Дзвін ключів', text: 'Тримайте зв’язку великих ключів поза досяжністю й тихо подзвоніть, пересуваючи її праворуч. Увесь час будьте поруч.', why: 'Металевий дзвін різко відрізняється від голосу та шелесту. Розрізнення тембру розширює звуковий досвід.' },
  { id: 'a062', from: 7, to: 12, minutes: 5, title: 'Спіймати усмішку', text: 'Повторіть вираз його обличчя: підняті брови, відкритий рот або усмішку. Почекайте, чи помітить малюк зміну.', why: 'Він дедалі краще читає рухи обличчя. Взаємне наслідування робить міміку першою спільною мовою.' },
  { id: 'a063', from: 7, to: 12, minutes: 7, title: 'Паперовий ліхтарик', text: 'Згорніть білий аркуш трубочкою й повільно рухайте ним перед малюком на темному тлі. Не підносьте близько до обличчя.', why: 'Світлий предмет на темному тлі легко виділяється. Зміна форми допомагає розрізняти контур речі.' },
  { id: 'a064', from: 7, to: 12, minutes: 6, title: 'Скласти й розгладити', text: 'Покладіть поряд тонку пелюшку, повільно зберіть її в складки та знову розгладьте. Коментуйте короткими словами.', why: 'Одна річ змінює вигляд, лишаючись собою. Це раннє знайомство зі сталістю предметів.' },
  { id: 'a065', from: 7, to: 12, minutes: 5, title: 'Танець брів', text: 'Сядьте навпроти й повільно піднімайте, а тоді опускайте брови. Після кожного руху завмирайте на кілька секунд.', why: 'Невеликий рух на обличчі легко помітити зблизька. Очікування паузи допомагає вловити послідовність.' },
  { id: 'a066', from: 7, to: 12, minutes: 8, title: 'М’ячик на животику', text: 'Покладіть легкий м’який м’яч на животик поверх одягу й обережно перекотіть до боку. Приберіть та повторіть з іншого боку.', why: 'Предмет, що котиться, дає шкірі відчуття напрямку. Рух можна не лише побачити, а й відчути.' },
  { id: 'a067', from: 7, to: 12, minutes: 5, title: 'Вітаю, дзеркало', text: 'Посадіть малюка біля дзеркала з опорою й скажіть: «ось ти». Нахиляйтеся поруч, щоб у дзеркалі були обоє облич.', why: 'Два обличчя в одній рамці привертають увагу до зв’язку між людьми. Малюк стежить, як рухи збігаються у відображенні.' },
  { id: 'a068', from: 7, to: 12, minutes: 6, title: 'Ритм долонею', text: 'Легенько постукуйте долонею по своїй нозі: два повільні удари й пауза. Повторюйте один малюнок, поки малюк слухає.', why: 'Ритм ділить суцільний звук на очікувані частини. Мозок починає вгадувати наступну паузу.' },
  { id: 'a069', from: 7, to: 12, minutes: 7, title: 'Угору до іграшки', text: 'Під час гри на животику покладіть яскраву іграшку трохи попереду й вище рук. За потреби підтримайте груди згорнутим рушником.', why: 'Погляд угору спонукає інакше спиратися на передпліччя. Плечі й шия отримують нове завдання втримувати положення.' },
  { id: 'a070', from: 7, to: 12, minutes: 4, title: 'Зміна капелюхів', text: 'Одягніть звичайну шапку, зніміть її та знову покажіть обличчя. Потім зав’яжіть на голові хустку й повторіть.', why: 'Обличчя лишається знайомим, попри зміну деталей довкола. Малюк вчиться впізнавати людину за сталими рисами.' },
  { id: 'a071', from: 7, to: 12, minutes: 6, title: 'Тепла пляшка', text: 'Дайте помацати зовні порожню пластикову пляшку кімнатної температури, тримаючи її разом із малюком. Трохи поверніть пляшку в долонях.', why: 'Гладка тверда поверхня відрізняється від тканини та шкіри. Поворот дає долоням відомості про форму.' },
  { id: 'a072', from: 7, to: 12, minutes: 5, title: 'Слова з іменем', text: 'Вставляйте ім’я малюка в простий ланцюжок: «ім’я, ось мама, ім’я, ось вікно». Щоразу вимовляйте його однаково.', why: 'Часто повторюване поєднання звуків починає виділятися серед інших слів. Ім’я стає помітною частиною мовлення.' },
  { id: 'a073', from: 7, to: 12, minutes: 6, title: 'Відкрита долоня', text: 'Розкрийте кулачок своєю долонею, поцілуйте центр долоньки й дайте пальчикам знову стиснутися. Чергуйте обидві руки.', why: 'Розкриття та стискання показують руці два різні положення. Зміна боків підтримує відчуття симетрії тіла.' },
  { id: 'a074', from: 7, to: 12, minutes: 7, title: 'Вітерець із книжки', text: 'Розгорнутою книжкою створіть слабкий вітерець біля рук малюка, а тоді покажіть саму книжку. Повторіть повільніше.', why: 'Невидимий потік повітря зіставляється з видимим рухом речі. Для відчуттів це маленька причинна загадка.' },
  { id: 'a075', from: 7, to: 12, minutes: 5, title: 'Червоне коло', text: 'Покажіть велике червоне паперове коло на світлій стіні та пересуньте його в інший бік. Дайте очам знайти коло.', why: 'Яскрава пляма відрізняється від нейтрального тла кольором і формою. Пошук після переміщення тренує зміну погляду.' },
  { id: 'a076', from: 7, to: 12, minutes: 6, title: 'Питальна інтонація', text: 'Скажіть одну коротку фразу спершу ствердно, а потім запитально. Спостерігайте, як змінюється вираз обличчя малюка.', why: 'Мелодія мовлення передає зміст раніше за слова. Малюк чує, як голос підвищується та знижується.' },
  { id: 'a077', from: 7, to: 12, minutes: 5, title: 'Рука в рукаві', text: 'Сховайте свою руку в широкий рукав, покажіть лише пальці, а згодом усю долоню. Повторіть кілька разів.', why: 'Частина знайомої речі стає підказкою про ціле. Це підготовка до майбутніх ігор зі зникненням і появою.' },
  { id: 'a078', from: 7, to: 12, minutes: 8, title: 'Повороти на килимку', text: 'Лежачи на спині, покладіть іграшку збоку, щоб малюк повернув до неї голову й плече. За хвилину змініть бік.', why: 'Поворот корпусу починається з цікавості до мети. Погляд поступово залучає плече й бік тіла в один рух.' },
  { id: 'a079', from: 7, to: 12, minutes: 4, title: 'Гучно й тихо', text: 'Двічі скажіть «ба» звичайним голосом, потім двічі тихіше. Між серіями зробіть паузу.', why: 'Той самий звук різної гучності вчить відокремлювати його від сили. Слух точніше працює серед побутового шуму.' },
  { id: 'a080', from: 7, to: 12, minutes: 7, title: 'Гора з пледа', text: 'Згорніть плед у невисокий валик і покладіть упоперек килимка під час гри на животику. Допоможіть спертися грудьми та роздивитися кімнату.', why: 'Нова висота змінює кут огляду й розподіл ваги на руках. Цікавий вид підтримує бажання побути на животику.' },
  { id: 'a081', from: 13, to: 18, minutes: 8, title: 'Кулька на нитці', text: 'Прив’яжіть легку кульку до короткої стрічки над килимком так, щоб малюк міг торкнутися її рукою. Увесь час будьте поруч.', why: 'Випадковий дотик викликає помітний рух перед очима. Малюк перевіряє, чи можна повторити цей ефект.' },
  { id: 'a082', from: 13, to: 18, minutes: 6, title: 'Розмова зі стопами', text: 'Підніміть стопи малюка до його долонь і назвіть одну «лівою», другу «правою». Легко з’єднайте стопи й розведіть.', why: 'Стопи дедалі частіше потрапляють у поле зору та стають частиною гри. З’єднання ніг допомагає відчути середню лінію тіла.' },
  { id: 'a083', from: 13, to: 18, minutes: 7, title: 'Котушка котиться', text: 'Прокотіть велику порожню котушку або картонну трубку підлогою перед малюком. Зупиніть біля руки, щоб можна було торкнутися.', why: 'Річ рухається після поштовху й поступово сповільнюється. Очі отримують перший приклад безперервного шляху.' },
  { id: 'a084', from: 13, to: 18, minutes: 5, title: 'Співуча склянка', text: 'Налийте трохи води в склянку та дуже легко проведіть ложкою по краю, тримаючи склянку поза досяжністю. Потім дайте почути звичайний стукіт ложки.', why: 'Один предмет може звучати по-різному залежно від дії. Порівняння допомагає розрізняти спосіб і результат.' },
  { id: 'a085', from: 13, to: 18, minutes: 9, title: 'Перекотитися через валик', text: 'На килимку покладіть згорнутий рушник під груди й розмістіть іграшку збоку. Допоможіть перенести вагу, якщо малюк тягнеться.', why: 'Вага зміщується з одного боку тіла на інший. Тіло отримує досвід, з якого згодом складуться повороти.' },
  { id: 'a086', from: 13, to: 18, minutes: 6, title: 'Стиснути губку', text: 'Намочіть велику чисту губку й трохи відіжміть над раковиною, щоб малюк побачив краплі. Дайте помацати губку разом із вами.', why: 'Форма м’якої речі змінюється від натискання. Одна дія одразу створює видимий і чутний результат.' },
  { id: 'a087', from: 13, to: 18, minutes: 7, title: 'Три обличчя', text: 'По черзі покажіть спокійний, здивований і веселий вираз обличчя. Між ними повертайтеся до нейтрального виразу.', why: 'Контраст міміки допомагає розрізняти зміни на знайомому обличчі. Малюк помічає емоційні сигнали без слів.' },
  { id: 'a088', from: 13, to: 18, minutes: 5, title: 'Кільця на руці', text: 'Одягніть на руку два великі браслети або кільця від пірамідки та повільно знімайте їх по одному. Дайте помацати кожне.', why: 'Предмети зникають із руки, проте лишаються поруч. Так легше відокремити місце речі від самої речі.' },
  { id: 'a089', from: 13, to: 18, minutes: 8, title: 'Упіймати хустинку', text: 'Плавно опустіть легку хустинку біля руки малюка й почекайте, чи потягнеться він. Будьте поруч і не лишайте хустинку без нагляду.', why: 'Тканина падає повільніше за іграшку та дає час спланувати захоплення. Рука вчиться обирати мить для руху.' },
  { id: 'a090', from: 13, to: 18, minutes: 6, title: 'Шелестить і мовчить', text: 'Покажіть два однакові на вигляд аркуші: один шелесткий, другий щільний. Стискайте їх по черзі, щоб малюк почув різницю.', why: 'Зір каже «схоже», а слух повідомляє «інакше». Така невідповідність збагачує порівняння властивостей речей.' },
  { id: 'a091', from: 13, to: 18, minutes: 7, title: 'Іграшка за плечем', text: 'Покажіть іграшку, а потім повільно перенесіть її за плече малюка й подзвоніть. Почекайте, поки він повернеться шукати.', why: 'Малюк утримує недавній образ іграшки, поки вона зникає з поля зору. Поворот до звуку перевіряє коротку пам’ять.' },
  { id: 'a092', from: 13, to: 18, minutes: 5, title: 'Оркестр губ', text: 'Обережно зробіть губами три різні звуки: «пф», «ммм», «ба». Після кожного дочекайтеся реакції малюка.', why: 'Незвичні звуки обличчя поєднуються з видимими рухами губ. Так малюк починає розуміти, звідки береться людське мовлення.' },
  { id: 'a093', from: 13, to: 18, minutes: 8, title: 'Дві іграшки', text: 'Покладіть у кожну руку по різній безпечній іграшці й подивіться, як малюк їх розглядає. Третю не пропонуйте.', why: 'Дві долоні одночасно отримують незалежні завдання. Мозок починає зіставляти відчуття правої та лівої руки.' },
  { id: 'a094', from: 13, to: 18, minutes: 6, title: 'Обличчя в рамці', text: 'Подивіться на малюка крізь порожню картонну рамку або долоні, складені колом. Повільно приберіть рамку й покажіться повністю.', why: 'Обличчя в рамці легше втримати поглядом. Зміна межі довкола нього допомагає виділити головний об’єкт.' },
  { id: 'a095', from: 13, to: 18, minutes: 7, title: 'М’яке падіння', text: 'Киньте з невеликої висоти на килимок легкий тканинний м’яч, щоб малюк бачив шлях. Потім покладіть м’яч у його долоню.', why: 'Падіння поєднує верх і низ в одну зорову послідовність. У долоні м’яч лишається тим самим предметом, який щойно рухався.' },
  { id: 'a096', from: 13, to: 18, minutes: 5, title: 'Долоня у воді', text: 'Під час купання хлюпніть долонею по воді поруч і дайте малюкові торкнутися поверхні. Будьте поряд.', why: 'Вода відповідає на дотик хвилями, а не лишається нерухомою. Для руки це новий різновид зворотного зв’язку.' },
  { id: 'a097', from: 13, to: 18, minutes: 8, title: 'Тягнемося до голосу', text: 'Під час гри на животику сядьте перед малюком і покличте короткою пісенькою, трохи змінюючи положення праворуч і ліворуч. Дайте повертати голову.', why: 'Знайомий голос стає метою, заради якої хочеться повернутися та припіднятися. Мотивація поєднує слух і рух.' },
  { id: 'a098', from: 13, to: 18, minutes: 6, title: 'Потягнути за стрічку', text: 'Покладіть іграшку на коротку широку стрічку й вкладіть край стрічки в долоню малюка. Покажіть, як підтягнути іграшку ближче.', why: 'Результат з’являється не від прямого дотику до іграшки, а через посередника. Це складніше за «схопив — отримав».' },
  { id: 'a099', from: 13, to: 18, minutes: 7, title: 'Бубон на коліні', text: 'Покладіть невеликий бубон собі на коліно й легко вдаряйте долонею в одному ритмі. Потім піднесіть руку малюка до поверхні.', why: 'Звук залежить від сили та місця удару. Спільна дія показує, що долоня теж може бути джерелом звуку.' },
  { id: 'a100', from: 13, to: 18, minutes: 5, title: 'Сердечка на папері', text: 'Намалюйте на аркуші два великі прості знаки різної форми й по черзі піднесіть ближче. Називайте: «коло», «сердечко».', why: 'Великі контури дають очам матеріал для розрізнення форми. Повтор назв поєднує сталий звук зі сталим виглядом.' },
  { id: 'a101', from: 13, to: 18, minutes: 8, title: 'Передаємо в іншу руку', text: 'Коли іграшка вже в одній руці, піднесіть другу долоню поруч і легко торкніться іграшки. Дайте час спробувати змінити руку.', why: 'Річ потрібно втримати, поки долучається друга рука. Це раннє узгодження двох рук.' },
  { id: 'a102', from: 13, to: 18, minutes: 6, title: 'Равлик із рушника', text: 'Згорніть рушник спіраллю та повільно розкрутіть на очах у малюка. Потім згорніть знову.', why: 'Той самий матеріал змінює форму поступово. Погляд стежить за перетворенням, а не за раптовим зникненням.' },
  { id: 'a103', from: 13, to: 18, minutes: 7, title: 'Пальчики вітаються', text: 'По черзі торкайтеся вказівним пальцем кожного пальчика малюка й кажіть «привіт». Зупиніться, щойно уваги стане забагато.', why: 'Окремі маленькі дотики дають долоні точнішу карту, ніж загальне погладжування. Ритм черги робить відчуття передбачуваними.' },
  { id: 'a104', from: 13, to: 18, minutes: 5, title: 'Далеко та близько', text: 'Покажіть іграшку на відстані витягнутої руки, а потім трохи наблизьте. Рухайте повільно й прямо.', why: 'Під час наближення розмір зображення для очей змінюється. Так зір знайомиться з глибиною.' },
  { id: 'a105', from: 13, to: 18, minutes: 8, title: 'Пісенька з паузою', text: 'Заспівайте знайому коротку пісеньку й зупиніться перед останнім словом. За секунду завершіть тим самим словом.', why: 'Повторювана послідовність створює очікування завершення. Мозок помічає коротке переривання звичного малюнка.' },
  { id: 'a106', from: 19, to: 26, minutes: 8, title: 'М’яч під стільцем', text: 'Прокотіть великий м’який м’яч під стільцем, щоб він з’явився з іншого боку. Нехай малюк стежить очима.', why: 'Предмет тимчасово ховається за перешкодою, проте продовжує шлях. Так міцнішає уявлення про безперервність руху.' },
  { id: 'a107', from: 19, to: 26, minutes: 10, title: 'Відкрити кришку', text: 'Дайте пластиковий контейнер із нещільною кришкою та великою іграшкою всередині. Один раз покажіть, як зняти кришку.', why: 'Щоб дістатися мети, слід змінити стан контейнера. Малюк пробує послідовність «відкрити, потім узяти».' },
  { id: 'a108', from: 19, to: 26, minutes: 7, title: 'Папір на голові', text: 'Покладіть легкий аркуш собі на голову й дайте малюку зняти його, тоді покладіть аркуш йому на плече. Будьте поруч.', why: 'Малюк помічає річ на людині та цілеспрямовано прибирає перешкоду. Дія спрямована вже не просто на предмет.' },
  { id: 'a109', from: 19, to: 26, minutes: 9, title: 'Прокоти до мене', text: 'Сядьте навпроти на підлозі й повільно прокотіть м’яч до малюка. Допоможіть спрямувати його назад, а потім дочекайтеся спроби.', why: 'Котіння потребує відпустити предмет у бік партнера. Так виникає спільна гра з одним шляхом.' },
  { id: 'a110', from: 19, to: 26, minutes: 6, title: 'Вгадай за звуком', text: 'За ширмою з рушника пошелестіть папером, дзенькніть ложкою об чашку та поплескайте. Після кожного звуку покажіть джерело.', why: 'Різні звуки починають вказувати на різні предмети. Відкриття джерела підтверджує слухову здогадку.' },
  { id: 'a111', from: 19, to: 26, minutes: 8, title: 'Вежа з коробок', text: 'Поставте дві легкі коробки одна на одну й дайте штовхнути верхню. Збудуйте знову без поспіху.', why: 'Падіння вежі показує, що розташування речей змінює результат. Малюк досліджує стійкість через дію.' },
  { id: 'a112', from: 19, to: 26, minutes: 7, title: 'Шарф у коробці', text: 'Сховайте кінець довгого шарфа в коробку, лишивши край зовні. Потягніть край і покажіть появу шарфа.', why: 'Частина предмета стає ключем до схованого цілого. Пошук виходить за межі того, що відразу видно.' },
  { id: 'a113', from: 19, to: 26, minutes: 10, title: 'Ложка й миска', text: 'Дайте порожню пластикову миску та велику ложку. Покажіть, як покласти ложку всередину й вийняти назад.', why: 'Вкладання та виймання знайомлять із «всередині» й «зовні». Просторові ідеї народжуються в руках.' },
  { id: 'a114', from: 19, to: 26, minutes: 5, title: 'Пауза в пісні', text: 'Заспівайте два знайомі склади та зупиніться, дивлячись на малюка. Продовжуйте після короткої тиші.', why: 'Малюк починає чекати продовження знайомого звукового малюнка. Пауза робить його учасником музичного обміну.' },
  { id: 'a115', from: 19, to: 26, minutes: 8, title: 'Картинка за картинкою', text: 'Покажіть дві великі картинки, одну сховайте за іншою та поміняйте місцями. Запитайте: «де кіт?».', why: 'Малюк стежить і за предметом, і за зміною його місця. Це тренує пам’ять про останнє розташування.' },
  { id: 'a116', from: 19, to: 26, minutes: 7, title: 'Натисни й послухай', text: 'Покладіть поруч пищальну іграшку й один раз натисніть. Дайте малюкові самому шукати спосіб повторити звук.', why: 'Дія стає навмисною, коли результат хочеться викликати знову. Рука пробує дібрати силу натискання.' },
  { id: 'a117', from: 19, to: 26, minutes: 9, title: 'Обійти подушку', text: 'Покладіть іграшку за невисокою подушкою, лишивши збоку вільний прохід. Покличте до іграшки, не пересуваючи перешкоду.', why: 'Прямий шлях закритий, тож потрібно помітити обхід. У русі з’являється перше просторове рішення.' },
  { id: 'a118', from: 19, to: 26, minutes: 6, title: 'Де долонька', text: 'Сховайте свою долоню під прозорою мискою та постукайте пальцями. Дайте малюкові побачити й спробувати дістати.', why: 'Прозора перешкода показує мету, проте не дає взяти її відразу. З’являється різниця між «бачу» і «можу дістати».' },
  { id: 'a119', from: 19, to: 26, minutes: 8, title: 'Великий і малий', text: 'Поставте поряд велику та малу м’які іграшки, назвіть їх і запропонуйте взяти одну. Потім змініть місця.', why: 'Розмір можна порівняти й без чисел. Малюк помічає сталу відмінність предметів однієї категорії.' },
  { id: 'a120', from: 19, to: 26, minutes: 7, title: 'Кулька у склянці', text: 'Покажіть, як опустити велику кульку в пластикову склянку та перевернути її, щоб кулька випала. Дайте спробувати.', why: 'Предмет змінює положення разом із контейнером. Малюк бачить зв’язок між переворотом і появою кульки.' },
  { id: 'a121', from: 19, to: 26, minutes: 10, title: 'Доріжки з рушників', text: 'Розкладіть дві різні доріжки: гладкий рушник і м’який килимок. Допоможіть доповзти кожною до однієї іграшки.', why: 'Тіло відчуває зміну поверхні під руками та колінами. Рух починає враховувати властивості простору.' },
  { id: 'a122', from: 19, to: 26, minutes: 5, title: 'Скажи, як я', text: 'Промовте короткий склад і дочекайтеся звуку малюка. Якщо відповість, повторіть саме його варіант, не виправляючи.', why: 'Лепет стає обміном, коли дорослий приймає відповідь. Малюк чує, що звук може впливати на іншу людину.' },
  { id: 'a123', from: 19, to: 26, minutes: 8, title: 'Хустинка в кільці', text: 'Протягніть край хустинки крізь велике кільце від пірамідки й потягніть. Дайте торкатися рухомого краю під наглядом.', why: 'Предмет проходить крізь отвір, не зникаючи. Очі та руки досліджують зв’язок форми отвору й руху тканини.' },
  { id: 'a124', from: 19, to: 26, minutes: 6, title: 'Тупотіння підлогою', text: 'Сидячи з опорою, м’яко поставте стопи малюка на підлогу й по черзі легко постукуйте ними. Кажіть «туп-туп».', why: 'Стопи створюють звук у контакті з твердою поверхнею. Рух ніг поєднується з ефектом назовні.' },
  { id: 'a125', from: 19, to: 26, minutes: 9, title: 'Взяти з кошика', text: 'Поставте неглибокий кошик із трьома великими безпечними речами. Дайте діставати по одній і розглядати.', why: 'Потрібно обрати одну річ серед кількох, не бачачи всього відразу. Увага перемикається між варіантами.' },
  { id: 'a126', from: 19, to: 26, minutes: 7, title: 'Губка плаває', text: 'У тазику з водою покладіть чисту губку на поверхню й трохи підштовхніть. Дайте поспостерігати, а потім торкнутися разом із вами.', why: 'У воді губка поводиться інакше, ніж на столі. Нове середовище змінює звичні властивості речі.' },
  { id: 'a127', from: 19, to: 26, minutes: 8, title: 'Перегорни сторінку', text: 'Відкрийте картонну книжку на яскравій сторінці, підніміть кутик і покладіть поруч пальчики малюка. Дайте завершити рух.', why: 'Сторінка одним рухом ховає одну картинку та відкриває іншу. Малюк вчиться керувати зміною зорової сцени.' },
  { id: 'a128', from: 19, to: 26, minutes: 6, title: 'Ладусі без слів', text: 'Візьміть долоньки малюка, м’яко зведіть разом, а потім розведіть. Повторіть кілька разів, інколи змінюючи паузу.', why: 'Дві руки зустрічаються посередині тіла та дають звук. Зміна паузи додає очікування простому руху.' },
  { id: 'a129', from: 19, to: 26, minutes: 9, title: 'Мета на дивані', text: 'Покладіть іграшку на низький край дивана, а самі сядьте поруч на підлозі. Дайте тягнутися до мети з опорою на руки.', why: 'Висота мети змушує перенести вагу вперед. Руки вчаться бути не лише захопленням, а й опорою.' },
  { id: 'a130', from: 19, to: 26, minutes: 7, title: 'Сховай звук', text: 'Загорніть дзвінку іграшку в рушник, щоб вона звучала приглушено. Розгорніть і порівняйте два звучання.', why: 'Матеріал довкола речі змінює чутний звук. Малюк помічає, що він залежить не лише від іграшки.' },
  { id: 'a131', from: 27, to: 36, minutes: 10, title: 'Проштовхни крізь трубу', text: 'Проштовхніть м’який м’яч крізь широку картонну трубу й дайте знайти його з другого боку.', why: 'М’яч зникає в трубі та з’являється у передбачуваному місці.' },
  { id: 'a132', from: 27, to: 36, minutes: 8, title: 'Кришки до мисок', text: 'Розкладіть дві пластикові миски й відповідні кришки, дозвольте приміряти їх.', why: 'Форма краю підказує, які частини пасують одна до одної.' },
  { id: 'a133', from: 27, to: 36, minutes: 9, title: 'Дай мамі', text: 'Попросіть передати конкретну знайому річ із двох: «дай ложку».', why: 'Слово спрямовує пошук серед предметів і додає дії спільну мету.' },
  { id: 'a134', from: 27, to: 36, minutes: 7, title: 'Кубик у чашці', text: 'Покажіть, як великий кубик потрапляє в чашку, а тоді відсуньте чашку.', why: 'Рука співвідносить напрямок із невеликим отвором.' },
  { id: 'a135', from: 27, to: 36, minutes: 10, title: 'Повзи за слідом', text: 'Протягніть яскраву стрічку від малюка до іграшки та покличте з іншого кінця.', why: 'Лінія перетворює далеку мету на видимі орієнтири.' },
  { id: 'a136', from: 27, to: 36, minutes: 6, title: 'Зняти шкарпетку', text: 'Трохи стягніть шкарпетку з п’яти й дайте малюкові завершити, залишаючись поруч.', why: 'Тканина чинить опір, поки її тягнуть у слушному напрямку.' },
  { id: 'a137', from: 27, to: 36, minutes: 8, title: 'Дзвінка й глуха ложка', text: 'Постукайте ложкою об металеву миску, а потім об рушник.', why: 'Один рух звучить інакше на різних поверхнях.' },
  { id: 'a138', from: 27, to: 36, minutes: 9, title: 'Поклади поруч', text: 'Покладіть дві іграшки на відстані та попросіть поставити одну біля іншої.', why: 'Слова про розташування набувають сенсу через дію.' },
  { id: 'a139', from: 27, to: 36, minutes: 7, title: 'Дзеркальний гребінець', text: 'Дайте безпечний гребінець і покажіть у дзеркалі, як провести ним по волоссю.', why: 'Малюк поєднує власний рух із рухом відображення.' },
  { id: 'a140', from: 27, to: 36, minutes: 10, title: 'Подушка-острів', text: 'Покладіть іграшку на подушку й залиште навколо вільний простір для руху.', why: 'Мета на підвищенні спонукає обрати шлях до неї.' },
  { id: 'a141', from: 27, to: 36, minutes: 6, title: 'Нагодуй ведмедика', text: 'Дайте ложку, мисочку й м’яку іграшку, покажіть один раз уявне годування.', why: 'Звичайна дія переходить у першу рольову гру.' },
  { id: 'a142', from: 27, to: 36, minutes: 8, title: 'Перевернутий кошик', text: 'Накрийте іграшку легким кошиком і покажіть, як підняти його.', why: 'Перешкоду потрібно прибрати, щоб дістати сховане.' },
  { id: 'a143', from: 27, to: 36, minutes: 7, title: 'Покажи, де', text: 'Запитайте «де м’яч?» серед кількох знайомих речей і дочекайтеся жесту.', why: 'Жест стає способом відповісти на запитання.' },
  { id: 'a144', from: 27, to: 36, minutes: 9, title: 'Витягни серветку', text: 'Лишіть край серветки назовні з коробки й запропонуйте потягнути.', why: 'Тягнення показує, як прихована частина продовжується всередині.' },
  { id: 'a145', from: 27, to: 36, minutes: 8, title: 'Один на одного', text: 'Покажіть, як поставити великий кубик на інший, і дайте спробувати.', why: 'Рівновага речей стає зрозумілою через власну дію.' },
  { id: 'a146', from: 27, to: 36, minutes: 6, title: 'Знайди такий самий', text: 'Покажіть дві однакові іграшки серед інших і попросіть знайти пару.', why: 'Схожість можна помітити попри сусідство різних речей.' },
  { id: 'a147', from: 27, to: 36, minutes: 10, title: 'Дверцята шафи', text: 'Відкрийте безпечну низьку шафку, покладіть усередину іграшку й дайте відкрити дверцята.', why: 'Рух дверцят змінює доступ до схованого предмета.' },
  { id: 'a148', from: 27, to: 36, minutes: 7, title: 'Прокоти похилою', text: 'Зробіть невеликий нахил із картону й пустіть м’яч униз.', why: 'Нахил спрямовує рух предмета без нового поштовху.' },
  { id: 'a149', from: 27, to: 36, minutes: 8, title: 'Музична зупинка', text: 'Увімкніть тиху музику, порухайтеся та завмріть, коли вона стихає.', why: 'Зупинка звуку стає помітним сигналом зміни дії.' },
  { id: 'a150', from: 27, to: 36, minutes: 9, title: 'Тарілка для іграшок', text: 'Поставте поруч тарілку й кілька іграшок, запропонуйте складати їх у неї.', why: 'Контейнер допомагає об’єднати різні предмети однією дією.' },
  { id: 'a151', from: 27, to: 36, minutes: 7, title: 'Перекинь через край', text: 'Покладіть м’яку іграшку біля краю низької коробки та покажіть рух через край.', why: 'Край стає просторовою межею, яку можна подолати.' },
  { id: 'a152', from: 27, to: 36, minutes: 8, title: 'Запитай жестом', text: 'Потримайте бажану іграшку й зачекайте на погляд, руку або звук, перш ніж дати її.', why: 'Малюк бачить, що жест може почати спільний обмін.' },
  { id: 'a153', from: 27, to: 36, minutes: 6, title: 'Сховай у рукаві', text: 'Сховайте маленьку іграшку у широкий рукав і дайте витягти її.', why: 'Частково прихована річ лишається предметом пошуку.' },
  { id: 'a154', from: 27, to: 36, minutes: 10, title: 'Марш до дзеркала', text: 'Пройдіть разом кілька кроків до дзеркала, зупиніться й помахайте відображенню.', why: 'Короткий маршрут поєднує рух, мету та знайому сцену.' },
  { id: 'a155', from: 27, to: 36, minutes: 7, title: 'Гортаємо разом', text: 'Тримайте картонну книжку вдвох і допоможіть перегорнути сторінку.', why: 'Спільний рух робить зміну сторінок передбачуваною.' },
  { id: 'a156', from: 37, to: 46, minutes: 10, title: 'Принеси подушку', text: 'Попросіть принести легку подушку з близького місця та покажіть, куди покласти.', why: 'Доручення поєднує слово, предмет і короткий маршрут.' },
  { id: 'a157', from: 37, to: 46, minutes: 8, title: 'Сліди крейдою', text: 'Намалюйте товстою крейдою просту доріжку й проведіть по ній іграшкою.', why: 'Слід на підлозі робить напрямок руху видимим.' },
  { id: 'a158', from: 37, to: 46, minutes: 7, title: 'Лялька в ліжечку', text: 'Покладіть ляльку в коробку-ліжечко та накрийте маленькою тканиною.', why: 'Предмети починають отримувати ролі в уявному сюжеті.' },
  { id: 'a159', from: 37, to: 46, minutes: 9, title: 'Чашка для води', text: 'Дайте дві пластикові чашки й разом перелийте трохи води над мискою.', why: 'Вода показує, що вміст можна переносити з посудини в посудину.' },
  { id: 'a160', from: 37, to: 46, minutes: 6, title: 'Сортуємо шкарпетки', text: 'Покладіть дві пари різних шкарпеток і запропонуйте знайти схожі.', why: 'Пара утворюється за помітною спільною ознакою.' },
  { id: 'a161', from: 37, to: 46, minutes: 8, title: 'Прокоти у ворота', text: 'Зробіть ворота з двох кубиків і покотіть м’яч крізь них разом.', why: 'Отвір дає рухові чітку ціль і напрямок.' },
  { id: 'a162', from: 37, to: 46, minutes: 10, title: 'Маленьке прибирання', text: 'Дайте ганчірку й запропонуйте витерти низький столик поруч із вами.', why: 'Наслідування побутової справи додає дії зрозумілу мету.' },
  { id: 'a163', from: 37, to: 46, minutes: 7, title: 'Високо й низько', text: 'Покладіть іграшку спершу на стілець, а тоді на підлогу, називаючи місце.', why: 'Перестановка показує, як змінюється відношення висоти.' },
  { id: 'a164', from: 37, to: 46, minutes: 9, title: 'Пошта у щілину', text: 'Зробіть широку щілину в коробці та запропонуйте опускати туди картонні картки.', why: 'Картку потрібно повернути й сумістити з отвором.' },
  { id: 'a165', from: 37, to: 46, minutes: 6, title: 'Назви на прогулянці', text: 'Зупиніться біля дерева чи машини й запитайте: «що це?». Прийміть будь-який жест або звук.', why: 'Назви закріплюються за предметами поза домом.' },
  { id: 'a166', from: 37, to: 46, minutes: 8, title: 'Будуємо міст', text: 'Накрийте дві книжки щільним картоном і прокотіть разом машинку через міст.', why: 'Конструкція з’єднує окремі місця та робить шлях можливим.' },
  { id: 'a167', from: 37, to: 46, minutes: 10, title: 'Приклей і зніми', text: 'Приклейте великий шматочок малярної стрічки до столу та покажіть, як відклеїти.', why: 'Липка поверхня спершу чинить опір, а потім відпускає.' },
  { id: 'a168', from: 37, to: 46, minutes: 7, title: 'Вежа по черзі', text: 'Будуйте вежу з великих кубиків по одному: один ставите ви, наступний — малюк.', why: 'Видимий результат допомагає зрозуміти чергу дій.' },
  { id: 'a169', from: 37, to: 46, minutes: 9, title: 'Знайди на картинці', text: 'Відкрийте сторінку з великою сценою та попросіть знайти кота, м’яч або чашку.', why: 'Увага утримує мету, поки очі оглядають деталі.' },
  { id: 'a170', from: 37, to: 46, minutes: 8, title: 'Загорни подарунок', text: 'Оберніть велику іграшку папером, лишивши вільний край, і запропонуйте розгорнути.', why: 'Щоб дістати предмет, потрібно прибрати оболонку.' },
  { id: 'a171', from: 37, to: 46, minutes: 6, title: 'Один і багато', text: 'Покажіть одну ложку, а потім кілька таких самих і назвіть «одна» та «багато».', why: 'Різниця між одиничною річчю та групою стає наочною.' },
  { id: 'a172', from: 37, to: 46, minutes: 9, title: 'Полий квітку', text: 'Разом полийте домашню рослину з маленької пластикової чашки, залишаючись поруч.', why: 'Дія спрямована на об’єкт, який змінюється від води.' },
  { id: 'a173', from: 37, to: 46, minutes: 7, title: 'Відкрий і закрий', text: 'Дайте контейнер із великою поворотною кришкою та покажіть обидва рухи.', why: 'Протилежні дії приводять до протилежних результатів.' },
  { id: 'a174', from: 37, to: 46, minutes: 10, title: 'Доріжка для машинки', text: 'Зробіть на підлозі широку паперову доріжку та котіть машинку до повороту.', why: 'Поворот змушує змінити напрямок, не втрачаючи мети.' },
  { id: 'a175', from: 37, to: 46, minutes: 6, title: 'Кому належить?', text: 'Покажіть свою чашку й чашку малюка, запитайте: «де мамина?», тоді поміняйте місцями.', why: 'Предмет упізнають і за зв’язком із людиною.' },
  { id: 'a176', from: 37, to: 46, minutes: 8, title: 'Хустинка танцює', text: 'Під тиху музику рухайте хустинкою вгору, вниз і колом, запропонуйте повторити рукою.', why: 'Ритм стає рухом усього тіла через наслідування.' },
  { id: 'a177', from: 37, to: 46, minutes: 9, title: 'Знайди за дверима', text: 'Сховайте знайому іграшку за прочиненими дверима, лишивши видимим маленький шматочок.', why: 'Видимий фрагмент стає знаком прихованого цілого.' },
  { id: 'a178', from: 37, to: 46, minutes: 7, title: 'Олівець у банку', text: 'Поставте широку пластикову банку та запропонуйте опускати в неї товсті олівці.', why: 'Вертикальний отвір потребує точного руху згори вниз.' },
  { id: 'a179', from: 37, to: 46, minutes: 10, title: 'Кому подзвонити', text: 'Візьміть іграшковий телефон і скажіть: «подзвони бабусі», показавши «алло».', why: 'Один предмет починає позначати інший, справжній.' },
  { id: 'a180', from: 37, to: 46, minutes: 8, title: 'Стрибок іграшки', text: 'Посадіть м’яку іграшку на край подушки та покажіть, як вона «стрибає» вниз.', why: 'Проста подія відтворюється в грі й стає маленькою історією.' },
  { id: 'a181', from: 47, to: 60, minutes: 10, title: 'Два доручення', text: 'Попросіть узяти м’яч і покласти його в кошик, показуючи жест лише за потреби.', why: 'Два кроки потрібно втримати в пам’яті до завершення.' },
  { id: 'a182', from: 47, to: 60, minutes: 8, title: 'Миємо іграшки', text: 'У тазику помийте пластикові іграшки губкою та запропонуйте малюкові його губку.', why: 'Послідовність «намочити, потерти, поставити» стає маленькою справою.' },
  { id: 'a183', from: 47, to: 60, minutes: 7, title: 'Частування для родини', text: 'Поставте іграшкові чашки й запропонуйте «дати чай» вам, ляльці та ведмедику.', why: 'Один сюжет розподіляється між кількома персонажами.' },
  { id: 'a184', from: 47, to: 60, minutes: 9, title: 'Сходинка-острів', text: 'На прогулянці оберіть низьку стійку сходинку й пройдіть угору та вниз, тримаючись за руку.', why: 'Зміна висоти потребує перенесення ваги й зупинки в новому положенні.' },
  { id: 'a185', from: 47, to: 60, minutes: 6, title: 'Чий голос?', text: 'Увімкніть короткі записи голосів близьких і запитайте, хто говорить.', why: 'Людину можна впізнати за характерним звучанням без обличчя.' },
  { id: 'a186', from: 47, to: 60, minutes: 10, title: 'Пазл із половинок', text: 'Розріжте листівку на дві великі нерівні частини й запропонуйте з’єднати картинку.', why: 'Цілий образ утримується в думці, поки руки шукають форму.' },
  { id: 'a187', from: 47, to: 60, minutes: 8, title: 'Гараж для машин', text: 'Поставте коробку набік, намалюйте два широкі в’їзди та запропонуйте паркувати машинки.', why: 'Коробка отримує нове значення завдяки уяві.' },
  { id: 'a188', from: 47, to: 60, minutes: 7, title: 'Скажи навпаки', text: 'Покажіть м’яч на столі, потім під стільцем і попросіть вказати нове місце.', why: 'Протилежні слова зрозумілі через одну річ у різних місцях.' },
  { id: 'a189', from: 47, to: 60, minutes: 9, title: 'Квиток в автобус', text: 'Поставте стільці рядком, зробіть паперові квитки й роздайте їх пасажирам-іграшкам.', why: 'Предмет має умовне значення всередині спільної гри.' },
  { id: 'a190', from: 47, to: 60, minutes: 6, title: 'Добери кришку', text: 'Змішайте три контейнери й три кришки та запропонуйте закрити кожен.', why: 'Потрібно порівнювати форми й пам’ятати перевірені варіанти.' },
  { id: 'a191', from: 47, to: 60, minutes: 10, title: 'Маршрут кімнатою', text: 'Скажіть: «спочатку до вікна, потім до крісла» й пройдіть шлях разом.', why: 'Маршрут зберігає два орієнтири у певному порядку.' },
  { id: 'a192', from: 47, to: 60, minutes: 8, title: 'Кому що потрібно', text: 'Покладіть ляльку, ложку, машинку й рушничок, запитайте, чим ляльці витерти руки.', why: 'Предмет обирають за призначенням, а не за кольором чи близькістю.' },
  { id: 'a193', from: 47, to: 60, minutes: 7, title: 'Знайди за описом', text: 'Попросіть знайти серед речей «те, чим малюють» або «те, що котиться».', why: 'Опис веде до предмета через його властивість чи дію.' },
  { id: 'a194', from: 47, to: 60, minutes: 9, title: 'День народження ведмедика', text: 'Посадіть іграшки навколо коробки-столу, зробіть «торт» із кришки й заспівайте привітання.', why: 'Сюжет поєднує персонажів, предмети та порядок подій.' },
  { id: 'a195', from: 47, to: 60, minutes: 6, title: 'Малюємо дощ', text: 'На великому аркуші покажіть короткі вертикальні лінії та назвіть їх дощем.', why: 'Лінія починає позначати явище, а не лише залишати слід.' },
  { id: 'a196', from: 47, to: 60, minutes: 8, title: 'Що зникло?', text: 'Покладіть три знайомі предмети, попросіть відвернутися та приберіть один.', why: 'Щоб помітити зникнення, потрібно порівняти пам’ять із тим, що лишилося.' },
  { id: 'a197', from: 47, to: 60, minutes: 10, title: 'Прання для ляльки', text: 'Дайте рушничок і миску, запропонуйте «попрати» ляльковий одяг без води.', why: 'Кілька наслідувальних дій поєднуються в один побутовий сюжет.' },
  { id: 'a198', from: 47, to: 60, minutes: 7, title: 'Коло й квадрат', text: 'Виріжте коло та квадрат із картону й запропонуйте покласти їх на відповідні контури.', why: 'Форма стає правилом вибору незалежно від кольору.' },
  { id: 'a199', from: 47, to: 60, minutes: 9, title: 'Полагодь дорогу', text: 'Зробіть розрив у паперовій доріжці та дайте картонний «місток» для машинки.', why: 'Ігрова проблема потребує обрати засіб, що підходить за функцією.' },
  { id: 'a200', from: 47, to: 60, minutes: 8, title: 'Розкажи картинками', text: 'Покладіть три картинки: дитина, м’яч, кошик, і запропонуйте розкласти їх за порядком.', why: 'Окремі зображення можна зібрати у просту послідовність подій.' },
];
